def generated_loss(batch, model_output, extra):
    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}

    alpha = 1.0
    if isinstance(extra, dict):
        alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))

    scale = float(hp.get('scale', 1.8))
    cost_coef = float(hp.get('cost_coef', 0.12))
    gap_clip = float(hp.get('gap_clip', 20.0))
    gap_softnorm = bool(hp.get('gap_softnorm', True))
    clamp_min = float(hp.get('clamp_min', -12.0))
    clamp_max = float(hp.get('clamp_max', 12.0))
    w_clip = float(hp.get('w_clip', 1e6))
    eps = float(hp.get('eps', 1e-6))

    # Robustly source required pairwise log-probs from batch/model_output with common aliases.
    lpw = batch.get('log_prob_w', batch.get('logprob_w', batch.get('chosen_logprob', batch.get('logp_w', None))))
    lpl = batch.get('log_prob_l', batch.get('logprob_l', batch.get('rejected_logprob', batch.get('logp_l', None))))
    if lpw is None and isinstance(model_output, dict):
        lpw = model_output.get('log_prob_w', model_output.get('logprob_w', model_output.get('chosen_logprob', model_output.get('logp_w', None))))
    if lpl is None and isinstance(model_output, dict):
        lpl = model_output.get('log_prob_l', model_output.get('logprob_l', model_output.get('rejected_logprob', model_output.get('logp_l', None))))

    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    if cost_a is None and isinstance(model_output, dict):
        cost_a = model_output.get('cost_a', None)
    if cost_b is None and isinstance(model_output, dict):
        cost_b = model_output.get('cost_b', None)

    base = cost_a
    if base is None:
        base = cost_b
    if base is None:
        base = lpw
    if base is None:
        base = lpl
    if base is None:
        base = ops.as_tensor(0.0)

    if lpw is None:
        lpw = ops.zeros_like(base)
    if lpl is None:
        lpl = ops.zeros_like(lpw)
    if cost_a is None:
        cost_a = ops.zeros_like(lpw)
    if cost_b is None:
        cost_b = ops.zeros_like(lpw)

    lp_gap = lpw - lpl

    cost_gap = (cost_b - cost_a).detach()
    cost_gap = ops.clamp(cost_gap, -gap_clip, gap_clip)
    if gap_softnorm:
        cost_gap = cost_gap / (ops.abs(cost_gap).mean() + eps)

    logit = alpha * scale * lp_gap - cost_coef * cost_gap
    logit = ops.clamp(logit, clamp_min, clamp_max)

    loss = -ops.logsigmoid(logit)

    w = batch.get('weight', None)
    if w is None and isinstance(model_output, dict):
        w = model_output.get('weight', None)

    if w is not None:
        w = ops.clamp(w, 0.0, w_clip)
        denom = ops.clamp(w.mean(), eps, w_clip)
        return (loss * w).sum() / denom

    return loss.mean()
